/**
 * [INPUT]: 依赖事务、ManagedModelStore、ProviderConnectionStore、bootstrap revision、AuditSink 与 ID generator。
 * [OUTPUT]: 对外提供模型 CRUD/排序/启停与 CAS；新增模型自动生成稳定 alias。
 * [POS]: model/application 的受管模型用例编排，连接决定真实路由。
 * [PROTOCOL]: 变更时更新此头部，然后检查 CLAUDE.md
 */
package com.owndsh.enterprise.model.application;

import com.owndsh.enterprise.audit.*;import com.owndsh.enterprise.model.domain.*;import com.owndsh.enterprise.model.persistence.*;import com.owndsh.enterprise.revision.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.transaction.support.TransactionOperations;import java.time.*;import java.util.*;import java.util.function.LongSupplier;

public final class ManagedModelService {
 private final TransactionOperations tx;private final ManagedModelStore models;private final ProviderConnectionStore connections;private final BootstrapRevisionStore revisions;private final AuditSink audit;private final LongSupplier ids;private final Clock clock;
 public ManagedModelService(TransactionOperations tx,ManagedModelStore models,ProviderConnectionStore connections,BootstrapRevisionStore revisions,AuditSink audit,LongSupplier ids){this(tx,models,connections,revisions,audit,ids,Clock.systemUTC());}
 ManagedModelService(TransactionOperations tx,ManagedModelStore models,ProviderConnectionStore connections,BootstrapRevisionStore revisions,AuditSink audit,LongSupplier ids,Clock clock){this.tx=tx;this.models=models;this.connections=connections;this.revisions=revisions;this.audit=audit;this.ids=ids;this.clock=clock;}
 public List<ManagedModel> list(String tenant,long after,int limit){return models.list(tenant,after,limit);} public ManagedModel get(String tenant,long id){return models.find(tenant,id).orElseThrow(ModelResourceNotFoundException::new);}
 public ManagedModel create(ModelMutationContext c,ManagedModelSpec spec){ProviderConnection route=connections.find(c.tenantId(),spec.connectionId()).orElseThrow(ModelResourceNotFoundException::new);ManagedModel m=build(positive(),c.tenantId(),route,spec,ModelStatus.ACTIVE,0);try{return Objects.requireNonNull(tx.execute(s->{models.insert(m);revisions.increment(c.tenantId());audit(c,m,ManagedModelChangeMetadata.Operation.CREATE);return m;}));}catch(DataIntegrityViolationException e){throw new IllegalArgumentException("模型别名或连接配置冲突",e);}}
 public ManagedModel update(ModelMutationContext c,long id,long expected,ManagedModelSpec spec){ManagedModel current=get(c.tenantId(),id);requireRevision(current,expected);ProviderConnection route=connections.find(c.tenantId(),spec.connectionId()).orElseThrow(ModelResourceNotFoundException::new);ManagedModel m=build(current.id(),c.tenantId(),route,spec,current.status(),expected+1);return Objects.requireNonNull(tx.execute(s->{if(!models.update(m,expected))throw conflict(c.tenantId(),id,expected);revisions.increment(c.tenantId());audit(c,m,ManagedModelChangeMetadata.Operation.UPDATE);return m;}));}
 public ManagedModel setStatus(ModelMutationContext c,long id,long expected,ModelStatus status){ManagedModel current=get(c.tenantId(),id);requireRevision(current,expected);ManagedModel m=new ManagedModel(current.id(),current.tenantId(),current.connectionId(),current.providerId(),current.providerName(),current.alias(),current.name(),current.modelId(),current.contextWindow(),current.maxTokens(),current.input(),current.reasoningEfforts(),current.reasoningCompat(),current.sortOrder(),status,expected+1);return Objects.requireNonNull(tx.execute(s->{if(!models.updateStatus(c.tenantId(),id,status,expected))throw conflict(c.tenantId(),id,expected);revisions.increment(c.tenantId());audit(c,m,status==ModelStatus.ACTIVE?ManagedModelChangeMetadata.Operation.ENABLE:ManagedModelChangeMetadata.Operation.DISABLE);return m;}));}
 public void delete(ModelMutationContext c,long id,long expected){ManagedModel current=models.find(c.tenantId(),id).orElse(null);if(current==null)return;requireRevision(current,expected);tx.executeWithoutResult(s->{ManagedModelDeleteBlockers b=models.deleteBlockers(c.tenantId(),id);if(!b.isEmpty())throw new ManagedModelInUseException(b);if(!models.delete(c.tenantId(),id,expected))throw conflict(c.tenantId(),id,expected);revisions.increment(c.tenantId());audit(c,current,ManagedModelChangeMetadata.Operation.DELETE);});}
 private ManagedModel build(long id,String tenant,ProviderConnection route,ManagedModelSpec spec,ModelStatus status,long revision){if(spec.reasoningCompat()!=null&&route.apiProtocol()!=ProviderApiProtocol.OPENAI_COMPLETIONS)throw new IllegalArgumentException("compat 仅适用于 openai-completions");String alias=generatedAlias(route,spec.modelId());return new ManagedModel(id,tenant,route.id(),route.providerId(),route.providerName(),alias,spec.name(),spec.modelId(),spec.contextWindow(),spec.maxTokens(),spec.input(),spec.reasoningEfforts(),spec.reasoningCompat(),spec.sortOrder(),status,revision);}
 private static String generatedAlias(ProviderConnection route,String modelId){String base=(route.providerName()+"-"+modelId).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9._-]+","-").replaceAll("-+","-").replaceAll("^-|-$","");String suffix="-c"+route.id();int max=120-suffix.length();if(base.length()>max)base=base.substring(0,max).replaceAll("-$","");return (base.isBlank()?"model":base)+suffix;}
 private void audit(ModelMutationContext c,ManagedModel m,ManagedModelChangeMetadata.Operation op){audit.append(new AuditEvent(positive(),c.tenantId(),Instant.now(clock),AuditActorType.USER,c.actorId(),null,AuditAction.MODEL_CHANGED,"MANAGED_MODEL",Long.toString(m.id()),AuditResult.SUCCESS,null,c.requestId(),c.sourceIp(),c.userAgentHash(),new ManagedModelChangeMetadata(op,m.revision(),revisions.current(c.tenantId()))));}
 private RevisionConflictException conflict(String t,long id,long e){return models.find(t,id).map(m->new RevisionConflictException(e,m.revision())).orElseThrow(ModelResourceNotFoundException::new);}private static void requireRevision(ManagedModel m,long e){if(e<0||m.revision()!=e)throw new RevisionConflictException(e,m.revision());}private long positive(){long i=ids.getAsLong();if(i<=0)throw new IllegalStateException("ID generator 必须返回正数");return i;}
}
